import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:frigo_zen/main.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:frigo_zen/screens/inventory/add_item_sheet.dart';
import 'package:frigo_zen/services/ocr_service.dart';

class InventoryScreen extends StatelessWidget {
  const InventoryScreen({super.key});

  // Get a stream of the user's inventory items
  Stream<QuerySnapshot> _getInventoryStream() {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      return Stream.empty();
    }
    return FirebaseFirestore.instance
        .collection('users')
        .doc(user.uid)
        .collection('inventory')
        .orderBy('createdAt', descending: true) 
        .snapshots(); 
  }

  // Delete an item from the inventory
  void _deleteItem(String docId) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    FirebaseFirestore.instance
        .collection('users')
        .doc(user.uid)
        .collection('inventory')
        .doc(docId)
        .delete();
  }

  void _incrementItem(String docId, int currentQuantity) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    FirebaseFirestore.instance
        .collection('users')
        .doc(user.uid)
        .collection('inventory')
        .doc(docId)
        .update({'quantity': currentQuantity + 1});
  }

  void _decrementItem(String docId, int currentQuantity) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    if (currentQuantity <= 1) {
      _deleteItem(docId);
    } else {
      FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .collection('inventory')
          .doc(docId)
          .update({'quantity': currentQuantity - 1});
    }
  }

  // This function now calls the OcrService
  void _showImageSourceDialog(BuildContext context) {
    final OcrService ocrService = OcrService();

    showModalBottomSheet(
      context: context,
      builder: (ctx) => SafeArea(child: Wrap(
        children: [
          // TODO: Uncomment the following lines to enable camera and gallery options
          /*
          ListTile(
            leading: const Icon(Icons.camera_alt),
            title: const Text('Take a Photo'),
            onTap: () {
              Navigator.of(ctx).pop();
              // This function call will need to be updated when the hack is removed
              // ocrService.pickAndProcessReceipt(context, ImageSource.camera); 
            },
          ),
          ListTile(
            leading: const Icon(Icons.photo_library),
            title: const Text('Choose from Gallery'),
            onTap: () {
              Navigator.of(ctx).pop();
              // This function call will need to be updated when the hack is removed
              // ocrService.pickAndProcessReceipt(context, ImageSource.gallery);
            },
          ),
          */
          // TODO: comment the following lines to enable camera and gallery options
            ListTile(
              leading: const Icon(Icons.photo),
              title: const Text('Use a testing Receipts'),
              onTap: () {
                Navigator.of(ctx).pop();
                final String fullBase64String = "";
                final String base64Image = fullBase64String.split(',').last;
                ocrService.pickAndProcessReceipt(context, base64Image);

              },
            )
        ]
      ))
    );
  }
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Inventory'), centerTitle: true, actions: [
          IconButton(
            icon: const Icon(Icons.receipt_long),
            tooltip: 'Scan Receipt',
            onPressed: () {
              _showImageSourceDialog(context);
            },
          ),
        ],),

      body: StreamBuilder<QuerySnapshot>(
        stream: _getInventoryStream(),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (snapshot.hasError) {
            return const Center(child: Text("An error occurred."));
          }

          if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
            return const Center(
              child: Text(
                "No items in your inventory. Tap + to add some!",
                textAlign: TextAlign.center,
              ),
            );
          }

          final items = snapshot.data!.docs;
          
          WidgetsBinding.instance.addPostFrameCallback((_) {
            final itemNames = items.map((item) {
              final data = item.data() as Map<String, dynamic>;
              return data['name'] as String;
            }).toList();
            context.read<InventoryProvider>().updateInventory(itemNames);
          });

          return ListView.builder(
            itemCount: items.length,
            itemBuilder: (context, index) {
              final item = items[index];
              final data = item.data() as Map<String, dynamic>;
              final String itemName = data['name'] ?? 'Unnamed Item';
              final int itemQuantity = data["quantity"] ?? 1;

              return Dismissible(
                key: Key(item.id),
                direction:
                    DismissDirection.endToStart, 
                onDismissed: (direction) {
                  _deleteItem(item.id);
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text("$itemName deleted."),
                      action: SnackBarAction(
                        label: "Cancel",
                        onPressed: () {
                          // (Logique d'annulation non implémentée pour le MVP)
                        },
                      ),
                    ),
                  );
                },
                background: Container(
                  color: Colors.red[700],
                  alignment: Alignment.centerRight,
                  padding: const EdgeInsets.only(right: 20),
                  child: const Icon(Icons.delete, color: Colors.white),
                ),
                child: ListTile(
                  title: Text(itemName),
                  trailing: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      IconButton(
                        icon: const Icon(Icons.remove_circle_outline),
                        onPressed: () {
                          _decrementItem(item.id, itemQuantity);
                        },
                      ),
                      Text(
                        itemQuantity.toString(),
                        style: Theme.of(context).textTheme.titleLarge,
                      ),
                      IconButton(
                        icon: const Icon(Icons.add_circle_outline),
                        onPressed: () {
                          _incrementItem(item.id, itemQuantity);
                        },
                      ),
                    ],
                  ),
                )
              );
            },
          );
        },
      ),

      floatingActionButton: FloatingActionButton(
        onPressed: () {
          showModalBottomSheet(
            context: context,
            isScrollControlled: true,
            builder: (ctx) => const AddItemSheet(),
          );
        },
        child: const Icon(Icons.add),
      ),
    );
  }
}
